def comps(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if (y,x) in seen: continue
            c=g[y][x]; st=[(y,x)]; seen.add((y,x)); cl=[]
            while st:
                cy,cx=st.pop(); cl.append((cy,cx))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==c:
                        seen.add((ny,nx)); st.append((ny,nx))
            out.append((c,sorted(cl)))
    return out
