def canon(sk):
    cells=tuple(sorted((y,x) for y,row in enumerate(sk.split('/')) for x,ch in enumerate(row) if ch=='#'))
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    def norm(cl):
        ys=[y for y,x in cl]; xs=[x for y,x in cl]
        return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cl))
    pts=[(y-min(ys),x-min(xs)) for y,x in cells]
    variants=set()
    cur=pts
    for _ in range(4):
        variants.add(norm(cur))
        variants.add(norm([(y,-x) for y,x in cur]))
        cur=[(x,max(y for y,_ in cur)-y) for y,x in cur]  # rotate
    return min(variants)

